print("partial+full ok")

for amt in ["0","-1"]:
    try: refund_shipping(mk(),Decimal(amt),T0); print("FAIL",amt)
    except BillingError as e: print("rejected",amt,e.code)

p=mk(); refund_shipping(p,Decimal("60.00"),T0)
try: refund_shipping(p,Decimal("50.00"),T0); print("FAIL over")
except BillingError as e: print("rejected over",e.code)

try: refund_shipping(mk("authorized"),Decimal("1.00"),T0); print("FAIL state")
except BillingError as e: print("rejected state",e.code)

# naive datetime
try: refund_shipping(mk(),Decimal("1.00"),datetime(2026,1,1)); print("FAIL naive")
except BillingError as e: print("rejected naive",e.code)

# rounding
p=mk(); refund_shipping(p,Decimal("10.005"),T0); print("rounded",p.refunded_amount)
